The configuration loading is inconsistent. Several new options (`autoAcceptFiles`, `autoJoinGroups`, `sessionIdleTimeout`, `dataDir`, `maxFileSize`) can be set in the JSON config file but are not supported as environment variables. For consistency with existing options like `SIMPLEX_PORT` and `SIMPLEX_AUTO_ACCEPT`, you should add support for overriding these new settings via environment variables as well. This will improve the bot's configurability in containerized environments.

```typescript
function loadEnvOverrides(): Partial<BotConfig> {
  const overrides: Partial<BotConfig> = {};

  if (process.env.SIMPLEX_PORT) {
    const port = Number(process.env.SIMPLEX_PORT);
    if (port >= 1 && port <= 65535) {
      overrides.port = port;
    }
  }

  if (process.env.SIMPLEX_HOST) {
    overrides.host = process.env.SIMPLEX_HOST;
  }

  if (process.env.SIMPLEX_BOT_NAME) {
    overrides.displayName = process.env.SIMPLEX_BOT_NAME;
  }

  if (process.env.SIMPLEX_AUTO_ACCEPT) {
    overrides.autoAcceptContacts = process.env.SIMPLEX_AUTO_ACCEPT === "true";
  }

  if (process.env.SIMPLEX_LOG_LEVEL) {
    const level = process.env.SIMPLEX_LOG_LEVEL;
    if (VALID_LOG_LEVELS.has(level)) {
      overrides.logLevel = level as BotConfig["logLevel"];
    }
  }

  if (process.env.SIMPLEX_TLS) {
    overrides.useTls = process.env.SIMPLEX_TLS === "true";
  }

  if (process.env.SIMPLEX_BUSINESS_ADDRESS) {
    overrides.businessAddress = process.env.SIMPLEX_BUSINESS_ADDRESS === "true";
  }

  if (process.env.SIMPLEX_AUTO_ACCEPT_FILES) {
    overrides.autoAcceptFiles = process.env.SIMPLEX_AUTO_ACCEPT_FILES === "true";
  }

  if (process.env.SIMPLEX_AUTO_JOIN_GROUPS) {
    overrides.autoJoinGroups = process.env.SIMPLEX_AUTO_JOIN_GROUPS === "true";
  }

  if (process.env.SIMPLEX_DATA_DIR) {
    overrides.dataDir = process.env.SIMPLEX_DATA_DIR;
  }

  return overrides;
}
```

